var timeStamp=new Date();localStorage.setItem("lastTimeStamp",timeStamp);var visual_updates=true;document.addEventListener('visibilitychange',function(){visual_updates=!document.hidden});var heartbeat_min_interval_ms=60000;var heartbeat_last_sent=0;function heartbeat(force){var now=Date.now();if((!force)&&(now-heartbeat_last_sent<heartbeat_min_interval_ms))return;heartbeat_last_sent=now;$.getJSON(base_url+"ajax/heartbeat.ajax.php",function(data){if(data.status!="1")return;localStorage.setItem("lastTimeStamp",new Date());var session_tz=session_end.tz();session_end_min=data.session_expire_after_minutes;session_end_seconds=data.session_end_seconds;session_end=moment.unix(session_end_seconds).tz(session_tz);$("#session-end").countdown(session_end.toDate(),session_countdown_tick)})}document.addEventListener("click",function(){heartbeat(false)},true);document.addEventListener("keydown",function(){heartbeat(false)},true);function timeChecker(maxMin){setInterval(function(){var storedTimeStamp=localStorage.getItem("lastTimeStamp");timeCompare(storedTimeStamp,maxMin)},10000)}function timeCompare(timeString,maxMin){var maxMinutes=maxMin;var currentTime=new Date();var pastTime=new Date(timeString);var timeDiff=currentTime-pastTime;var minPast=Math.floor((timeDiff/60000));if(minPast>=maxMinutes){localStorage.removeItem("lastTimeStamp");if(visual_updates){$(".modal").modal('hide');$(".modal-backdrop").remove()}window.location=session_end_redirect;return false}}window.addEventListener("storage",function(event){if(event.key!=="lastTimeStamp")return;if(!event.newValue)return;var session_tz=session_end.tz();session_end=moment().tz(session_tz).add(session_end_min,'minutes');session_end_seconds=session_end.unix();$("#session-end").countdown(session_end.toDate(),session_countdown_tick)});timeChecker(session_end_min);function session_countdown_tick(event){if(session_end_min>1440){var end_time=(event.strftime('%D:%H:%M:%S'))}else if(session_end_min>60){var end_time=(event.strftime('%H:%M:%S'))}else{var end_time=(event.strftime('%M:%S'))}$(this).html(end_time);var session_end_total_seconds=session_end_min*60;if(visual_updates){if((session_end_total_seconds>120)&&((end_time=="02:00")||(end_time=="00:02:00")||(end_time=="00:00:02:00"))){$(".modal").modal('hide');$(".modal-backdrop").remove();$("#session-expire-warning").modal('show')}if((session_end_total_seconds>30)&&((end_time=="00:30")||(end_time=="00:00:30")||(end_time=="00:00:00:30"))){$(".modal").modal('hide');$(".modal-backdrop").remove();$("#session-expire-warning-30").modal('show')}}}$("#session-end").countdown(session_end.toDate(),session_countdown_tick);
